#include <bits/stdc++.h>
#include <omp.h>
using namespace std; using Arr=array<uint8_t,8>;
static const double V[8][7]={{4.3368086899420177e-17,0.48943915401716565,-0.2573711701187591,0.44577994304914381,-0.44591493030279611,0.25744910504599255,-0.36769135668039343},{-0.48943915401716553,7.9797279894933126e-17,-0.25737117011875937,-0.44577994304914353,0.25744910504599255,-0.44591493030279611,0.36769135668039338},{0.48943915401716559,-9.384495385472472e-17,-0.25737117011875882,0.44577994304914398,-0.25744910504599244,-0.44591493030279605,0.36769135668039338},{5.6725457664441592e-16,0.48943915401716559,-0.25737117011875904,-0.44577994304914381,0.44591493030279589,0.25744910504599283,-0.36769135668039343},{-1.6653345369377348e-16,-0.48943915401716553,-0.25737117011875871,0.44577994304914398,0.44591493030279605,-0.25744910504599261,-0.36769135668039343},{0.48943915401716559,-2.0643209364124004e-16,-0.25737117011875987,-0.4457799430491432,-0.25744910504599267,0.44591493030279611,0.36769135668039338},{-0.48943915401716559,1.1307217996749377e-15,-0.25737117011875937,0.4457799430491437,0.257449105045992,0.4459149303027965,0.36769135668039338},{0,0,0,0,0,0,0}};
// fix last row initialized separately due compact typo guard
static const double V7[7]={5.4296844798074062e-16,-0.48943915401716559,-0.25737117011876004,-0.4457799430491432,-0.44591493030279561,-0.25744910504599328,-0.36769135668039338};
static const int P[8][8]={{0,1,2,3,4,5,6,7},{2,3,4,5,6,7,0,1},{4,5,6,7,0,1,2,3},{6,7,0,1,2,3,4,5},{7,6,5,4,3,2,1,0},{1,0,7,6,5,4,3,2},{3,2,1,0,7,6,5,4},{5,4,3,2,1,0,7,6}};
uint32_t enc(const Arr&a){uint32_t x=0;for(int i=0;i<8;i++)x|=(uint32_t)a[i]<<(4*i);return x;} Arr decodec(uint32_t x){Arr a{};for(int i=0;i<8;i++)a[i]=(x>>(4*i))&15;return a;} int total(const Arr&a){int s=0;for(auto x:a)s+=x;return s;} bool lexle(const Arr&a,const Arr&b){for(int i=0;i<8;i++){if(a[i]<b[i])return true;if(a[i]>b[i])return false;}return true;}
uint32_t canon(const Arr&a){uint32_t best=UINT32_MAX;Arr t{};for(int g=0;g<8;g++){t.fill(0);for(int i=0;i<8;i++)t[P[g][i]]=a[i];best=min(best,enc(t));}return best;}
struct Stat{double lz=0,d1=0,d2=0;array<double,4>lev{};}; double alpha0; unordered_map<uint64_t,Stat>M; unordered_map<uint32_t,double>NORM; uint64_t ky(uint32_t c,int q){return ((uint64_t)q<<32)|c;}
double normc(const Arr&a){uint32_t e=enc(a);auto it=NORM.find(e);if(it!=NORM.end())return it->second;double t[7]={0};for(int i=0;i<8;i++)for(int d=0;d<7;d++)t[d]+=a[i]*(i==7?V7[d]:V[i][d]);double s=0;for(double z:t)s+=z*z;NORM[e]=s;return s;}
Stat get(const Arr&a,int q){if(total(a)==1)return Stat{};return M.at(ky(canon(a),q));}
void enumraw(int idx,int rem,int cap,Arr&a,vector<Arr>&out){if(idx==8){if(rem==0)out.push_back(a);return;}int tail=(7-idx)*cap;for(int x=max(0,rem-tail);x<=min(cap,rem);x++){a[idx]=x;enumraw(idx+1,rem-x,cap,a,out);}a[idx]=0;}
vector<Arr> raws(int m,int cap){vector<Arr>o;Arr a{};enumraw(0,m,cap,a,o);return o;}
void splitsrec(const Arr&c,int idx,int rem,Arr&a,vector<pair<Arr,Arr>>&o){if(idx==8){if(rem==0){Arr b{};for(int i=0;i<8;i++)b[i]=c[i]-a[i];if(lexle(a,b))o.push_back({a,b});}return;}int tail=0;for(int i=idx+1;i<8;i++)tail+=c[i];for(int x=max(0,rem-tail);x<=min((int)c[idx],rem);x++){a[idx]=x;splitsrec(c,idx+1,rem-x,a,o);}a[idx]=0;}
Stat eval(const Arr&c,int q){int m=total(c);vector<pair<Arr,Arr>>sp;Arr a{};splitsrec(c,0,m/2,a,sp);double nc=normc(c),fac=8.0*q/m;struct Br{double lw,d1,d2;array<double,4>lev;};vector<Br>b;b.reserve(sp.size()*2);for(auto &pr:sp){auto x=pr.first,y=pr.second;double de=(2*normc(x)+2*normc(y)-nc)/m,rd=-fac*de;auto X=get(x,q);if(x!=y){auto Y=get(y,q);Br z{ -alpha0*fac*de+X.lz+Y.lz,rd+X.d1+Y.d1,X.d2+Y.d2,{}};for(int k=0;k<4;k++)z.lev[k]=X.lev[k]+Y.lev[k];b.push_back(z);}else{Br z1{-alpha0*fac*de+2*X.lz-log(2.0),rd+2*X.d1,2*X.d2,{}};for(int k=0;k<4;k++)z1.lev[k]=2*X.lev[k];b.push_back(z1);auto X2=get(x,q*2);Br z2{-alpha0*fac*de+X2.lz-log(2.0),rd+X2.d1,X2.d2,X2.lev};b.push_back(z2);}}
double mx=-INFINITY;for(auto&z:b)mx=max(mx,z.lw);double sw=0;for(auto&z:b)sw+=exp(z.lw-mx);Stat out;out.lz=mx+log(sw);for(auto&z:b){double p=exp(z.lw-out.lz);out.d1+=p*z.d1;}double between=0,within=0;for(auto&z:b){double p=exp(z.lw-out.lz);between+=p*(z.d1-out.d1)*(z.d1-out.d1);within+=p*z.d2;}out.d2=between+within;out.lev[0]=between;for(auto&z:b){double p=exp(z.lw-out.lz);for(int k=0;k<3;k++)out.lev[k+1]+=p*z.lev[k];}return out;}
int main(int argc,char**argv){alpha0=argc>1?stod(argv[1]):0.8245;int th=argc>2?stoi(argv[2]):5;omp_set_num_threads(th);M.reserve(100000);NORM.reserve(500000);for(int m:{2,4,8,16})for(int q:{8,4,2,1}){int cap=8/q;if(m>8*cap)continue;auto r=raws(m,cap);vector<uint32_t> cs;for(auto&a:r)cs.push_back(canon(a));sort(cs.begin(),cs.end());cs.erase(unique(cs.begin(),cs.end()),cs.end());vector<Stat>s(cs.size());
#pragma omp parallel for schedule(dynamic,32)
 for(long long i=0;i<(long long)cs.size();i++)s[i]=eval(decodec(cs[i]),q);for(size_t i=0;i<cs.size();i++)M[ky(cs[i],q)]=s[i];cerr<<"m "<<m<<" q "<<q<<" states "<<cs.size()<<"\n";}
auto r=raws(16,8);cout<<setprecision(17);for(auto&a:r){cout<<hex<<enc(a)<<dec;for(int q:{1,2,4}){bool ok=true;for(auto x:a)if(x>8/q)ok=false;if(!ok){for(int k=0;k<7;k++)cout<<" nan";continue;}auto s=get(a,q);cout<<" "<<s.lz<<" "<<s.d1<<" "<<s.lev[0]<<" "<<s.lev[1]<<" "<<s.lev[2]<<" "<<s.lev[3]<<" "<<s.d2;}cout<<"\n";}}
